svg.script:
(function(){
  const svgNS = 'http://www.w3.org/2000/svg';
  const components = [
    { n: 1, amp: 1.00, phaseDeg:   0, color: '#ff7f50', freqLabel: 'f' },
    { n: 2, amp: 0.60, phaseDeg:  30, color: '#ffb347', freqLabel: '2f' },
    { n: 3, amp: 0.38, phaseDeg: -45, color: '#ffd166', freqLabel: '3f' },
    { n: 4, amp: 0.28, phaseDeg:  90, color: '#06d6a0', freqLabel: '4f' },
    { n: 5, amp: 0.24, phaseDeg: -110, color: '#118ab2', freqLabel: '5f' },
    { n: 6, amp: 0.18, phaseDeg: 160, color: '#5e60ce', freqLabel: '6f' },
    { n: 7, amp: 0.14, phaseDeg: -200, color: '#ff6fb7', freqLabel: '7f' }
  ];

  const baseDuration = 14;
  components.forEach(c => c.phase = c.phaseDeg * Math.PI / 180);

  const sampleCount = 480;
  const totalT = Math.PI * 4; // two full periods of the fundamental
  const leftX0 = 80;
  const leftWidth = 400;
  const leftYCenter = 400;
  const leftYScale = 115;
  const compX0 = 520;
  const compWidth = 330;
  const compStartY = 170;
  const compSpacing = 75;
  const compScale = 55;

  const compositePath = document.getElementById('composite-path');
  const componentsPanel = document.getElementById('components-panel');
  const connectorsGroup = document.getElementById('connectors');
  const magnitudePanel = document.getElementById('magnitude-panel');
  const phasePanel = document.getElementById('phase-panel');

  const mapCompositeX = ratio => leftX0 + ratio * leftWidth;
  const mapCompositeY = val => leftYCenter - val * leftYScale;

  function compositeValue(t){
    return components.reduce((sum, comp) => sum + comp.amp * Math.sin(comp.n * t + comp.phase), 0);
  }

  function buildPath(mapX, mapY, valueFn){
    let d = '';
    for(let i=0; i<sampleCount; i++){
      const ratio = i / (sampleCount - 1);
      const t = ratio * totalT;
      const val = valueFn(t);
      const x = mapX(ratio);
      const y = mapY(val);
      d += (i === 0 ? 'M ' : ' L ') + x.toFixed(2) + ' ' + y.toFixed(2);
    }
    return d;
  }

  compositePath.setAttribute('d', buildPath(r => mapCompositeX(r), mapCompositeY, compositeValue));
  compositePath.setAttribute('pathLength', leftWidth.toString());
  compositePath.style.setProperty('--duration', baseDuration + 's');

  components.forEach((comp, index) => {
    const axisY = compStartY + index * compSpacing;
    const axisLine = document.createElementNS(svgNS, 'line');
    axisLine.setAttribute('x1', compX0);
    axisLine.setAttribute('y1', axisY);
    axisLine.setAttribute('x2', compX0 + compWidth);
    axisLine.setAttribute('y2', axisY);
    axisLine.setAttribute('class', 'mini-axis');
    componentsPanel.appendChild(axisLine);

    const label = document.createElementNS(svgNS, 'text');
    label.setAttribute('x', compX0 - 30);
    label.setAttribute('y', axisY - 14);
    label.setAttribute('class', 'component-label');
    const phaseText = (comp.phaseDeg >= 0 ? '+' : '') + comp.phaseDeg.toFixed(0) + '°';
    label.textContent = `${comp.amp.toFixed(2)} · sin(${comp.freqLabel}t ${phaseText})`;
    componentsPanel.appendChild(label);

    const path = document.createElementNS(svgNS, 'path');
    path.setAttribute('class', 'component-wave wave-path');
    path.setAttribute('stroke', comp.color);
    path.style.setProperty('--duration', (baseDuration / comp.n).toFixed(2) + 's');
    path.setAttribute('pathLength', compWidth.toString());
    const localPath = buildPath(r => compX0 + r * compWidth, val => axisY - val * compScale, t => comp.amp * Math.sin(comp.n * t + comp.phase));
    path.setAttribute('d', localPath);
    componentsPanel.appendChild(path);

    const sampleT = ((index + 1) / (components.length + 1)) * totalT;
    const endX = mapCompositeX(sampleT / totalT);
    const endY = mapCompositeY(compositeValue(sampleT));
    const connector = document.createElementNS(svgNS, 'line');
    connector.setAttribute('x1', compX0 + compWidth + 25);
    connector.setAttribute('y1', axisY);
    connector.setAttribute('x2', endX);
    connector.setAttribute('y2', endY);
    connector.setAttribute('class', 'contribution-line');
    connectorsGroup.appendChild(connector);

    const dot = document.createElementNS(svgNS, 'circle');
    dot.setAttribute('cx', endX);
    dot.setAttribute('cy', endY);
    dot.setAttribute('r', 4);
    dot.setAttribute('class', 'contribution-dot');
    connectorsGroup.appendChild(dot);
  });

  const maxAmp = Math.max(...components.map(c => c.amp));
  const magBaseY = 720;
  const magTopY = 520;
  const magHeight = magBaseY - magTopY;
  const barWidth = 32;
  const availableWidth = 360;
  const gap = (availableWidth - barWidth * components.length) / (components.length - 1);
  let cursorX = 980;

  components.forEach(comp => {
    const height = (comp.amp / maxAmp) * magHeight;
    const bar = document.createElementNS(svgNS, 'rect');
    bar.setAttribute('x', cursorX);
    bar.setAttribute('y', magBaseY - height);
    bar.setAttribute('width', barWidth);
    bar.setAttribute('height', height);
    bar.setAttribute('class', 'magnitude-bar');
    bar.setAttribute('fill', comp.color);
    magnitudePanel.appendChild(bar);

    const freqLabel = document.createElementNS(svgNS, 'text');
    freqLabel.setAttribute('x', cursorX + barWidth / 2);
    freqLabel.setAttribute('y', magBaseY + 18);
    freqLabel.setAttribute('class', 'small-label');
    freqLabel.textContent = comp.freqLabel;
    magnitudePanel.appendChild(freqLabel);

    const valueLabel = document.createElementNS(svgNS, 'text');
    valueLabel.setAttribute('x', cursorX + barWidth / 2);
    valueLabel.setAttribute('y', magBaseY - height - 8);
    valueLabel.setAttribute('class', 'value-label');
    valueLabel.textContent = comp.amp.toFixed(2);
    magnitudePanel.appendChild(valueLabel);

    cursorX += barWidth + gap;
  });

  const phaseCols = 4;
  const radius = 34;
  const phaseStartX = 980;
  const phaseStartY = 180;
  const phaseXGap = 100;
  const phaseYGap = 110;

  components.forEach((comp, index) => {
    const col = index % phaseCols;
    const row = Math.floor(index / phaseCols);
    const cx = phaseStartX + col * phaseXGap;
    const cy = phaseStartY + row * phaseYGap;

    const circle = document.createElementNS(svgNS, 'circle');
    circle.setAttribute('cx', cx);
    circle.setAttribute('cy', cy);
    circle.setAttribute('r', radius);
    circle.setAttribute('class', 'phase-circle');
    circle.setAttribute('stroke', comp.color);
    phasePanel.appendChild(circle);

    const needle = document.createElementNS(svgNS, 'line');
    needle.setAttribute('x1', cx);
    needle.setAttribute('y1', cy);
    needle.setAttribute('x2', (cx + radius * Math.cos(comp.phase)).toFixed(2));
    needle.setAttribute('y2', (cy - radius * Math.sin(comp.phase)).toFixed(2));
    needle.setAttribute('class', 'phase-needle');
    needle.setAttribute('stroke', comp.color);
    phasePanel.appendChild(needle);

    const runner = document.createElementNS(svgNS, 'g');
    runner.setAttribute('class', 'phase-runner');
    runner.style.setProperty('--duration', (baseDuration / comp.n).toFixed(2) + 's');
    runner.style.setProperty('--phase', comp.phaseDeg + 'deg');
    runner.style.transformOrigin = `${cx}px ${cy}px`;
    const runnerDot = document.createElementNS(svgNS, 'circle');
    runnerDot.setAttribute('cx', cx);
    runnerDot.setAttribute('cy', cy - radius);
    runnerDot.setAttribute('r', 4);
    runnerDot.setAttribute('fill', comp.color);
    runner.appendChild(runnerDot);
    phasePanel.appendChild(runner);

    const label = document.createElementNS(svgNS, 'text');
    label.setAttribute('x', cx);
    label.setAttribute('y', cy + radius + 18);
    label.setAttribute('class', 'phase-label');
    const phaseText = (comp.phaseDeg >= 0 ? '+' : '') + comp.phaseDeg.toFixed(0) + '°';
    label.textContent = `${comp.freqLabel} ${phaseText}`;
    phasePanel.appendChild(label);
  });
})();
